  image[sr][sc] = color
  while (stack.length) {
    const [r, c] = stack.pop()
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr
      const nc = c + dc
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] === old) {
        image[nr][nc] = color
        stack.push([nr, nc])
      }
    }
  }
  return image
}

