function taskOrder(n, deps) {
  const graph = Array.from({ length: n }, () => [])
  const indegree = new Array(n).fill(0)
  for (const [a, b] of deps) {
    graph[a].push(b)
    indegree[b]++
  }
  const ready = new Set()
  for (let v = 0; v < n; v++) if (indegree[v] === 0) ready.add(v)
  const order = []
  while (ready.size) {
    let node = Infinity
    for (const v of ready) if (v < node) node = v   // smallest ready label
    ready.delete(node)
    order.push(node)
    for (const nxt of graph[node]) {
      indegree[nxt]--
      if (indegree[nxt] === 0) ready.add(nxt)
    }
  }
  return order.length === n ? order : []
}

