function pacificAtlantic(heights) {
  const rows = heights.length
  const cols = heights[0].length
  // Mark every cell that can drain into the ocean whose edge cells are in starts.
  const reach = (starts) => {
    const seen = Array.from({ length: rows }, () => new Array(cols).fill(false))
    const stack = []
    for (const [r, c] of starts) {
      if (!seen[r][c]) {
        seen[r][c] = true
        stack.push([r, c])
      }
    }
    while (stack.length > 0) {
      const [r, c] = stack.pop()
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr
        const nc = c + dc
        // walk uphill: water could flow from (nr, nc) down to (r, c)
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc] && heights[nr][nc] >= heights[r][c]) {
          seen[nr][nc] = true
          stack.push([nr, nc])
        }
      }
    }
    return seen
  }
  const pacificStarts = []
  const atlanticStarts = []
  for (let r = 0; r < rows; r++) {
    pacificStarts.push([r, 0])
    atlanticStarts.push([r, cols - 1])
  }
  for (let c = 0; c < cols; c++) {
    pacificStarts.push([0, c])
    atlanticStarts.push([rows - 1, c])
  }
  const pacific = reach(pacificStarts)
  const atlantic = reach(atlanticStarts)
  const out = []
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) if (pacific[r][c] && atlantic[r][c]) out.push([r, c])
  }
  return out
}

