function networkDelay(times, n, k) {
  const adj = Array.from({ length: n + 1 }, () => [])
  for (const [u, v, w] of times) adj[u].push([v, w])
  const done = new Map() // node -> final shortest time
  const heap = new MinHeap((a, b) => a[0] - b[0]) // [time, node], earliest first
  heap.push([0, k])
  while (heap.size > 0) {
    const [time, node] = heap.pop()
    if (done.has(node)) continue // already settled with an earlier time
    done.set(node, time)
    for (const [next, w] of adj[node]) {
      if (!done.has(next)) heap.push([time + w, next])
    }
  }
  return done.size === n ? Math.max(...done.values()) : -1
}

