import heapq


def network_delay(times, n, k):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    done = {}                           # node -> final shortest time
    heap = [(0, k)]                     # (time, node), earliest first
    while heap:
        time, node = heapq.heappop(heap)
        if node in done:
            continue                    # already settled with an earlier time
        done[node] = time
        for nxt, w in adj[node]:
            if nxt not in done:
                heapq.heappush(heap, (time + w, nxt))
    return max(done.values()) if len(done) == n else -1
